           PORT1 : in  STD_LOGIC_VECTOR (17 downto 0);
           PORT2 : in  STD_LOGIC_VECTOR (17 downto 0);
           NEW_SAMPLE : in  STD_LOGIC;
			  NSAMPLES : in STD_LOGIC_VECTOR (12 downto 0);
