	signal mult3_b : std_logic_vector(17 downto 0);
	signal mult3_c : std_logic_vector(47 downto 0);
	signal mult3_p : std_logic_vector(47 downto 0);

	signal mult4_a : std_logic_vector(17 downto 0);
	signal mult4_b : std_logic_vector(17 downto 0);
	signal mult4_c : std_logic_vector(47 downto 0);
	signal mult4_p : std_logic_vector(47 downto 0);

	signal mult_enable : std_logic;
	signal mult_accumulate : std_logic_vector(0 downto 0);
begin

	LookupTable : SinCos
	PORT MAP (
		clk => CLK,
		phase_in => phase(31 downto 20),
		cosine => cosine,
		sine => sine
	);
	Mult1 : DSP_SLICE
	PORT MAP (
		clk => CLK,
		ce => mult_enable,
		sel => mult_accumulate,
		a => mult1_a,
		b => mult1_b,
		c => mult1_c,
		p => mult1_p
	);
	Mult2 : DSP_SLICE
	PORT MAP (
		clk => CLK,
		ce => mult_enable,
		sel => mult_accumulate,
		a => mult2_a,
		b => mult2_b,
		c => mult2_c,
		p => mult2_p
	);
	Mult3 : DSP_SLICE
	PORT MAP (
		clk => CLK,
		ce => mult_enable,
		sel => mult_accumulate,
		a => mult3_a,
		b => mult3_b,
		c => mult3_c,
		p => mult3_p
	);
	Mult4 : DSP_SLICE
	PORT MAP (
		clk => CLK,
		ce => mult_enable,
		sel => mult_accumulate,
		a => mult4_a,
		b => mult4_b,
		c => mult4_c,
		p => mult4_p
	);

	result_ram: result_bram
	PORT MAP (
		clka => CLK,
		wea => we,
		addra => write_address_vector,
		dina => ram_in,
		clkb => CLK,
		addrb => read_address_vector,
		doutb => ram_out
	);

	read_address_vector <= std_logic_vector(to_unsigned(read_address, 8));
	write_address_vector <= std_logic_vector(to_unsigned(write_address, 8));
	OUTPUT <= ram_out;

	mult1_c <= ram_out(191 downto 144);
	mult2_c <= ram_out(143 downto 96);
	mult3_c <= ram_out(95 downto 48);
	mult4_c <= ram_out(47 downto 0);

	ram_in <= mult1_p & mult2_p & mult3_p & mult4_p;

	process(CLK, RESET)
	begin
		if rising_edge(CLK) then
			if RESET = '1' then
				mult_enable <= '0';
				mult_accumulate <= "0";
				sample_cnt <= 0;
				RESULT_READY <= '0';
				read_address <= 0;
				write_address <= 0;
				we <= "0";
				state <= WaitingForSample;
			else
				samples_to_take <= to_integer(unsigned(NSAMPLES & "0000")) - 1;
				case state is
					when WaitingForSample =>
						we <= "0";
						mult_enable <= '0';
						mult_accumulate <= "0";
						read_address <= 0;
						write_address <= 0;
						if NEW_SAMPLE = '1' then
							-- calculate phase for initial bin
							mult1_a <= std_logic_vector(to_unsigned(sample_cnt, 18));
							mult1_b <= "00" & BIN1_PHASEINC;
							mult2_a <= std_logic_vector(to_unsigned(sample_cnt, 18));
							mult2_b <= "00" & DIFFBIN_PHASEINC;
							state <= WaitMult;
							bin_cnt <= 0;
							mult_enable <= '1';
						end if;
					when WaitMult =>
						RESULT_READY <= '0';
						we <= "0";
						mult_enable <= '1';
						mult_accumulate <= "0";
						read_address <= 0;
						write_address <= 0;
						if bin_cnt < 4 then
							bin_cnt <= bin_cnt + 1;
						else
							bin_cnt <= 0;
							mult_enable <= '0';
							state <= WaitSinCos;
							phase <= mult1_p(15 downto 0) & "0000000000000000";
							phase_inc <= mult2_p(23 downto 0) & "00000000";
							port1_latch <= PORT1;
							port2_latch <= PORT2;
						end if;
					when WaitSinCos =>
						phase <= std_logic_vector(unsigned(phase)+unsigned(phase_inc));
						RESULT_READY <= '0';
						we <= "0";
						mult_enable <= '0';
						mult_accumulate <= "0";
						read_address <= 0;
						write_address <= 0;
						if bin_cnt < 6 then
							bin_cnt <= bin_cnt + 1;
						else
							bin_cnt <= 0;
							mult_enable <= '1';
							read_address <= 1;
							-- sign extended multiplication
							mult1_a <= port1_latch;
							mult1_b <= sine(15) & sine(15) & sine;
							mult2_a <= port1_latch;
							mult2_b <= cosine(15) & cosine(15) & cosine;
							mult3_a <= port2_latch;
							mult3_b <= sine(15) & sine(15) & sine;
							mult4_a <= port2_latch;
							mult4_b <= cosine(15) & cosine(15) & cosine;
							state <= BUSY;
							if sample_cnt = 0 then
								mult_accumulate <= "0";
							else
								mult_accumulate <= "1";
							end if;
						end if;
					when BUSY =>
						mult_enable <= '1';
						if sample_cnt = 0 then
							mult_accumulate <= "0";
						else
							mult_accumulate <= "1";
						end if;
						RESULT_READY <= '0';
						phase <= std_logic_vector(unsigned(phase)+unsigned(phase_inc));
						-- sign extended multiplication
						mult1_a <= port1_latch;
						mult1_b <= sine(15) & sine(15) & sine;
						mult2_a <= port1_latch;
						mult2_b <= cosine(15) & cosine(15) & cosine;
						mult3_a <= port2_latch;
						mult3_b <= sine(15) & sine(15) & sine;
						mult4_a <= port2_latch;
						mult4_b <= cosine(15) & cosine(15) & cosine;
						if bin_cnt >= 3 then
							-- multiplier result is available, advance write address
							we <= "1";
							write_address <= bin_cnt - 3;
						else
							we <= "0";
							write_address <= 0;
						end if;
						if bin_cnt >= BINS+2 then
							read_address <= 0;
							if sample_cnt < samples_to_take then
								sample_cnt <= sample_cnt + 1;
								state <= WaitingForSample;
							else
								state <= Ready;
							end if;
						else
							bin_cnt <= bin_cnt + 1;
							if bin_cnt < BINS - 2 then
								read_address <= bin_cnt + 2;
							end if;
						end if;
					when Ready =>
						we <= "0";
						RESULT_READY <= '1';
						write_address <= 0;
						if NEXT_OUTPUT = '1' then
							-- fetch next entry from RAM
							if read_address < BINS - 1 then
